package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class LookupTranslator_translate_TriageGen1Test {

    @Test
    public void testTranslate_SuccessGreedy() throws IOException {
        // Setup: longest=2, shortest=1. Map: "ab" -> "X", "a" -> "Y"
        // Tests the greedy descending loop (picks "ab" over "a")
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"ab"}, 
                new CharSequence[]{"X"},
                new CharSequence[]{"a"}, 
                new CharSequence[]{"Y"}
        );

        StringWriter out = new StringWriter();
        String input = "abc";

        // Test matching "ab" at index 0
        int result = translator.translate(input, 0, out);

        assertEquals(2, result);
        assertEquals("X", out.toString());
    }

    @Test
    public void testTranslate_SuccessShortest() throws IOException {
        // Setup: longest=1, shortest=1. Map: "a" -> "X"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"}, 
                new CharSequence[]{"X"}
        );

        StringWriter out = new StringWriter();
        String input = "abc";

        int result = translator.translate(input, 0, out);

        assertEquals(1, result);
        assertEquals("X", out.toString());
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        // Setup: Map: "a" -> "X"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"}, 
                new CharSequence[]{"X"}
        );

        StringWriter out = new StringWriter();
        String input = "bc";

        // Test index 0 where no match exists
        int result = translator.translate(input, 0, out);

        assertEquals(0, result);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_BoundaryCondition_IndexAtEndOfInput() throws IOException {
        // Setup: longest=2, shortest=1. Map: "a" -> "X"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"}, 
                new CharSequence[]{"X"}
        );

        StringWriter out = new StringWriter();
        String input = "abc";

        // Test index 3 (length of input), loop should not execute or handle gracefully
        int result = translator.translate(input, 3, out);

        assertEquals(0, result);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_BoundaryCondition_PartialLengthMatch() throws IOException {
        // Setup: longest=5, shortest=1. Map: "ab" -> "X"
        // Input "abc" at index 0. index + longest (0+5) > input.length (3).
        // max should become 3 - 0 = 3.
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"ab"}, 
                new CharSequence[]{"X"}
        );

        StringWriter out = new StringWriter();
        String input = "abc";

        int result = translator.translate(input, 0, out);

        assertEquals(2, result);
        assertEquals("X", out.toString());
    }

    @Test
    public void testTranslate_MatchAtTail() throws IOException {
        // Setup: longest=1, shortest=1. Map: "c" -> "Z"
        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"c"}, 
                new CharSequence[]{"Z"}
        );

        StringWriter out = new StringWriter();
        String input = "abc";

        // Test index 2
        int result = translator.translate(input, 2, out);

        assertEquals(1, result);
        assertEquals("Z", out.toString());
    }

    @Test(expected = IOException.class)
    public void testTranslate_ThrowsIOException() throws IOException {
        // Custom Writer that throws IOException
        class ThrowingWriter extends StringWriter {
            @Override
            public void write(String str) throws IOException {
                throw new IOException("Simulated error");
            }
        }

        LookupTranslator translator = new LookupTranslator(
                new CharSequence[]{"a"}, 
                new CharSequence[]{"X"}
        );

        translator.translate("a", 0, new ThrowingWriter());
    }
}
